#!/usr/bin/perl
use strict;
use warnings;
use File::Find;

my $repo = '/bench/repo';

# Collect all declarations in internal/
my @decls;  # {name, recv, pkg, file, line, qual}

sub strip_comments_strings {
    my ($code) = @_;
    # crude: remove // comments, /* */, and strings
    $code =~ s{//.*$}{}gm;
    $code =~ s{/\*.*?\*/}{}gs;
    $code =~ s{"(?:\\.|[^"\\])*"}{""}g;
    $code =~ s{'(?:\\.|[^'\\])*'}{""}g;
    $code =~ s{`(?:\\.|[^`\\])*`}{""}g;
    return $code;
}

find({
    wanted => sub {
        return unless /\.go$/;
        return if /_test\.go$/;
        return unless $File::Find::name =~ m{^$repo/internal/};
        open my $fh, '<', $_ or return;
        my $content = do { local $/; <$fh> };
        close $fh;
        my $pkg = 'unknown';
        if ($content =~ /^package\s+(\w+)/m) { $pkg = $1; }
        my @lines = split /\n/, $content;
        for my $i (0..$#lines) {
            my $line = $lines[$i];
            if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_]\w*)\s*\(/) {
                my ($recv, $name) = ($1, $2);
                my $recv_type = '';
                if (defined $recv && $recv =~ /\*?(\w+)/) {
                    $recv_type = $1;
                }
                push @decls, {
                    name => $name,
                    recv => $recv_type,
                    pkg => $pkg,
                    file => $File::Find::name,
                    line => $i + 1,
                    is_method => ($recv_type ne '') ? 1 : 0,
                };
            }
        }
    },
    no_chdir => 1,
}, "$repo/internal");

# Build file contents cache (all go files, exclude tests optionally - include tests for completeness)
my %files;
find({
    wanted => sub {
        return unless /\.go$/;
        open my $fh, '<', $_ or return;
        my $raw = do { local $/; <$fh> };
        close $fh;
        $files{$File::Find::name} = $raw;
    },
    no_chdir => 1,
}, $repo);

# Count call sites for each declaration
my @results;

for my $d (@decls) {
    my $name = $d->{name};
    my $count = 0;
    my %caller_funcs;  # distinct caller functions

    for my $fpath (keys %files) {
        my $raw = $files{$fpath};
        my $clean = strip_comments_strings($raw);
        my @lines = split /\n/, $clean;

        # track current function for distinct caller counting
        my $cur_func = '(toplevel)';
        my $cur_pkg = 'unknown';
        if ($raw =~ /^package\s+(\w+)/m) { $cur_pkg = $1; }

        for my $i (0..$#lines) {
            my $orig_line = (split /\n/, $raw)[$i] // '';
            # update current function from original (not stripped) lines
            if ($orig_line =~ /^func\s+(?:\([^)]+\)\s+)?([A-Za-z_]\w*)\s*\(/) {
                $cur_func = "$cur_pkg.$1";
            }

            my $line = $lines[$i];
            # skip declaration line in the declaring file
            if ($fpath eq $d->{file} && ($i + 1) == $d->{line}) {
                next;
            }
            # skip lines that are func declarations
            next if $orig_line =~ /^func\s+/;

            my $matched = 0;
            if ($d->{is_method}) {
                # method call: .MethodName(
                if ($line =~ /\.\Q$name\E\s*\(/) {
                    $matched = 1;
                }
            } else {
                # function call: bare Name( or pkg.Name(
                if ($line =~ /(?:^|[^\w.])(\Q$name\E)\s*\(/ || $line =~ /\.(\Q$name\E)\s*\(/) {
                    # For bare calls, need to be in same package OR it's exported and called with pkg prefix
                    if ($line =~ /(?:^|[^\w.])(\Q$name\E)\s*\(/) {
                        $matched = 1;
                    }
                }
                # Also match pkg/name prefix for cross-package
                if ($line =~ /[\w.]+\.\Q$name\E\s*\(/) {
                    $matched = 1;
                }
            }

            if ($matched) {
                $count++;
                $caller_funcs{"$fpath:$cur_func"} = 1;
            }
        }
    }

    push @results, {
        %$d,
        call_sites => $count,
        distinct_callers => scalar keys %caller_funcs,
        caller_funcs => \%caller_funcs,
    };
}

@results = sort { $b->{call_sites} <=> $a->{call_sites} || $b->{distinct_callers} <=> $a->{distinct_callers} } @results;

print "TOP 30 by call_sites:\n";
for my $i (0..29) {
    my $r = $results[$i];
    last unless $r;
    my $qual = $r->{is_method} ? "($r->{recv}).$r->{name}" : $r->{name};
    printf "%4d sites, %3d callers | %s | %s:%d\n", $r->{call_sites}, $r->{distinct_callers}, $qual, $r->{file}, $r->{line};
}

print "\nTOP 30 by distinct_callers:\n";
my @by_callers = sort { $b->{distinct_callers} <=> $a->{distinct_callers} || $b->{call_sites} <=> $a->{call_sites} } @results;
for my $i (0..29) {
    my $r = $by_callers[$i];
    last unless $r;
    my $qual = $r->{is_method} ? "($r->{recv}).$r->{name}" : $r->{name};
    printf "%4d sites, %3d callers | %s | %s:%d\n", $r->{call_sites}, $r->{distinct_callers}, $qual, $r->{file}, $r->{line};
}
